#!/usr/bin/env bash
#
# Post-`tauri ios init` patches for the iOS build. `gen/apple` is gitignored
# and regenerated by `tauri ios init`, so this MUST run AFTER init and BEFORE
# `tauri ios build`. Idempotent. Invoked from codemagic.yaml.
#
# The iOS-only Info.plist keys (local network, Files app sharing, ATS) need no
# patch here: `tauri ios build` merges client/src-tauri/Info.ios.plist itself.
#
# 1) App icons: `tauri ios init` seeds the Tauri placeholder icon set. The
#    committed PS5Upload set in client/src-tauri/icons/ios uses the same file
#    names as AppIcon.appiconset, so it is copied over on every build.

set -euo pipefail

root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
apple="$root/client/src-tauri/gen/apple"
iconset="$apple/Assets.xcassets/AppIcon.appiconset"

if [ ! -d "$iconset" ]; then
  echo "::error::AppIcon.appiconset not found at $iconset — run 'tauri ios init' first" >&2
  exit 1
fi

icons="$root/client/src-tauri/icons/ios"
if [ -d "$icons" ]; then
  cp -v "$icons"/*.png "$iconset/"
  echo "applied the PS5Upload app icons"
fi
